sys_script_include.script:
var OffboardingUtils = Class.create();
OffboardingUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    /**
     * Retrieves active IT hardware assets assigned to the target user.
     * Called asynchronously via GlideAjax.
     * 
     * @returns {string} JSON string containing asset count and status message.
     */
    getEmployeeAssetSummary: function() {
        var userId = this.getParameter('sysparm_user_id');
        var response = {
            success: false,
            assetCount: 0,
            message: ''
        };

        if (!userId) {
            response.message = 'Target user ID is missing.';
            return JSON.stringify(response);
        }

        try {
            var assetGr = new GlideRecord('alm_hardware');
            assetGr.addQuery('assigned_to', userId);
            assetGr.addQuery('install_status', '!=', 7); // Exclude 'Retired'
            assetGr.query();

            response.assetCount = assetGr.getRowCount();
            response.success = true;
            response.message = 'Successfully retrieved assets count.';

            gs.info('[OffboardingUtils] Found ' + response.assetCount + ' active assets for user: ' + userId);
        } catch (ex) {
            response.message = 'Error querying asset records.';
            gs.error('[OffboardingUtils] Exception in getEmployeeAssetSummary: ' + ex.message);
        }

        return JSON.stringify(response);
    },

    type: 'OffboardingUtils'
});
